package org.doutitle.commands;import org.doutitle.DouTitle;import org.doutitle.api.Title;import org.bukkit.Bukkit;import org.bukkit.command.Command;import org.bukkit.command.CommandExecutor;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import java.util.regex.Matcher;import java.util.regex.Pattern;public class DouTitleCommand implements CommandExecutor {    private final DouTitle plugin;    public DouTitleCommand(DouTitle plugin) {        this.plugin = plugin;    }    @Override    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {        if (args.length == 0) {            sendHelp(sender);            return true;        }        switch (args[0].toLowerCase()) {            case "open":                if (sender instanceof Player) {                    plugin.getOpenGUI().open((Player) sender);                } else {                    sender.sendMessage("§c只有玩家才能执行此命令！");                }                break;            case "shop":                if (sender instanceof Player) {                    plugin.getShopGUI().open((Player) sender);                } else {                    sender.sendMessage("§c只有玩家才能执行此命令！");                }                break;            case "create":                if (!sender.hasPermission("doutitle.admin")) {                    sender.sendMessage("§c你没有权限！");                    return true;                }                if (args.length < 4) {                    sender.sendMessage("§c用法: /doutitle create <称号id> <称号名> <时间>");                    sender.sendMessage("§c时间格式: -1永久, 1s秒, 1m分, 1h小时, 1d天, 1w周, 1y年");                    return true;                }                String id = args[1];                String name = args[2];                String timeStr = args[3];                long duration = parseTime(timeStr);                plugin.getTitleManager().createTitle(id, name, duration);                sender.sendMessage("§a已创建称号: " + name + " (ID: " + id + ")");                break;            case "give":                if (!sender.hasPermission("doutitle.admin")) {                    sender.sendMessage("§c你没有权限！");                    return true;                }                if (args.length < 4) {                    sender.sendMessage("§c用法: /doutitle give <玩家名> <称号id> <时间>");                    sender.sendMessage("§c时间格式: -1永久, 1s秒, 1m分, 1h小时, 1d天, 1w周, 1y年");                    return true;                }                Player target = Bukkit.getPlayer(args[1]);                if (target == null) {                    sender.sendMessage("§c玩家不在线！");                    return true;                }                String titleId = args[2];                String giveTimeStr = args[3];                long giveDuration = parseTime(giveTimeStr);                plugin.getTitleManager().giveTitle(target, titleId, giveDuration);                sender.sendMessage("§a已给予 " + target.getName() + " 称号: " + titleId);                break;            case "delete":                if (!sender.hasPermission("doutitle.admin")) {                    sender.sendMessage("§c你没有权限！");                    return true;                }                if (args.length < 2) {                    sender.sendMessage("§c用法: /doutitle delete <称号id>");                    return true;                }                String deleteId = args[1];                plugin.getTitleManager().deleteTitle(deleteId);                sender.sendMessage("§a已删除称号: " + deleteId);                break;            case "reload":                if (!sender.hasPermission("doutitle.admin")) {                    sender.sendMessage("§c你没有权限！");                    return true;                }                plugin.reload();                sender.sendMessage("§a插件配置已重载！");                break;            default:                sendHelp(sender);                break;        }        return true;    }    private void sendHelp(CommandSender sender) {        sender.sendMessage("§6=== DouTitle 插件帮助 ===");        sender.sendMessage("§e/doutitle open §7- 打开称号仓库");        sender.sendMessage("§e/doutitle shop §7- 打开称号商店");        sender.sendMessage("§e/doutitle create <id> <名称> <时间> §7- 创建称号");        sender.sendMessage("§e/doutitle give <玩家> <id> <时间> §7- 给予称号");        sender.sendMessage("§e/doutitle delete <id> §7- 删除称号");        sender.sendMessage("§e/doutitle reload §7- 重载插件");        sender.sendMessage("§7时间格式: -1永久, 1s秒, 1m分, 1h小时, 1d天, 1w周, 1y年");    }    private long parseTime(String timeStr) {        if (timeStr.equals("-1")) {            return -1;        }        Pattern pattern = Pattern.compile("(\\d+)([smhdwy])");        Matcher matcher = pattern.matcher(timeStr.toLowerCase());        if (matcher.matches()) {            long value = Long.parseLong(matcher.group(1));            String unit = matcher.group(2);            switch (unit) {                case "s": return value;                case "m": return value * 60;                case "h": return value * 60 * 60;                case "d": return value * 24 * 60 * 60;                case "w": return value * 7 * 24 * 60 * 60;                case "y": return value * 365 * 24 * 60 * 60;                default: return -1;            }        }        return -1;    }}